-- This file is the whole day: remove the day's stories that are no longer in it
delete from news_stories where publish_date = '2026-11-15' and (slug is null or slug not in ($n$2026-11-15-noel-tata-listing$n$, $n$2026-11-15-india-us-trade-deal$n$, $n$2026-11-15-senco-gold-q2$n$, $n$2026-11-15-microsoft-outage-restored$n$, $n$2026-11-15-brent-weekly-loss$n$, $n$2026-11-15-musk-nvidia-handshake$n$, $n$2026-11-15-patanjali-foods-q2$n$, $n$2026-11-15-trai-spam-crackdown$n$, $n$2026-11-15-vaishnaw-chip-machines$n$, $n$2026-11-15-eepc-east-bengal-policy$n$, $n$2026-11-15-cci-advent-yatharth$n$, $n$2026-11-15-pollution-insurance-claims$n$));

insert into news_stories (slug, publish_date, lane, tag, headline, summary, concept_note, source_name, source_url, card_id, status, teaser_title, teaser, featured, published_at, rank)
values
($n$2026-11-15-noel-tata-listing$n$, '2026-11-15', $n$recruiter$n$, $n$GOVERNANCE$n$,
  $n$Noel Tata says listing Tata Sons could change the 'Tata way' and put profits ahead of philanthropy$n$,
  $n$Tata Trusts chairman Noel Tata said on Saturday that a stock market listing of Tata Sons, which some shareholders are pushing for, could change how the group is run. Speaking at the HT Leadership Summit, he argued that with 30,000 to 40,000 shareholders, profit might one day take priority over the charity work the Trusts fund. The Trusts, which control about 66% of Tata Sons, oppose a listing, while the Shapoorji Pallonji Group, which owns 18.37%, supports one. The question became pressing after the RBI turned down Tata Sons' September application to give up its registration as a core investment company, a step that would have let it avoid a mandatory listing. Noel Tata said the Trusts would work with regulators to find a way forward, and added that the group's direction is sound but its very large projects need tighter execution.$n$,
  $n$The profit-maximisation view says a company exists to make money for its shareholders, while the stakeholder view says it must also serve employees, society and other groups. Noel Tata's worry is that thousands of new shareholders would pull Tata Sons towards the first view.$n$,
  $n$Business Today; also The Tribune (PTI), Free Press Journal$n$, $n$https://www.businesstoday.in/latest/corporate/story/my-worry-is-that-listing-will-change-the-tata-way-noel-tata-fears-profit-over-philanthropy-567483-2026-11-14$n$, $n$ethics-13$n$, 'draft',
  $n$The head of the trusts that own two-thirds of Tata Sons fears a listing would put profit before charity.$n$,
  $n$Noel Tata said that bringing in tens of thousands of shareholders could change the 'Tata way', while the Shapoorji Pallonji Group wants the listing. An RBI ruling has pushed the question onto the table. The profit maximisation vs stakeholder card explains the two sides.$n$, false, $n$2026-11-14T18:57:00+05:30$n$, 1),
($n$2026-11-15-india-us-trade-deal$n$, '2026-11-15', $n$india$n$, $n$TRADE$n$,
  $n$India-US trade deal is in its 'last stretch' with most issues settled, including tariff lines, says Jaishankar$n$,
  $n$External Affairs Minister S Jaishankar said on Saturday that India and the US have resolved most issues in their proposed trade deal, including tariff lines, and that it could be sealed soon. Speaking at the HT Leadership Summit, he said India hopes the talks are in the last stretch and that recent changes have come more from the American side than India's. He said India wants a balanced deal that gives its goods better tariffs in the US market than those of its competitors, and called the US India's biggest market. Negotiations have run since early 2025, and relations were strained after Washington imposed punitive tariffs on India that year. The remarks come about a month before the G20 summit in Miami on December 14-15, which Prime Minister Narendra Modi is likely to attend.$n$,
  $n$Tariffs and trade deals are political and economic forces that sit outside any single company's control, yet they decide how competitive Indian exporters are abroad. The PESTLE framework is how managers track such macro-environment shifts.$n$,
  $n$Free Press Journal (PTI)$n$, $n$https://www.freepressjournal.in/india/india-us-trade-deal-nears-final-breakthrough-as-eam-s-jaishankar-says-bulk-of-issues-resolved$n$, $n$mkt-05$n$, 'draft',
  $n$India's biggest export market may soon cut it a better tariff deal than its rivals get.$n$,
  $n$Jaishankar said most issues in the India-US trade talks, including tariff lines, are settled and the deal is in its last stretch. For exporters, a tariff edge over competitors could matter more than any marketing plan. The marketing environment card explains why macro forces shape every business.$n$, false, $n$2026-11-14T17:39:00+05:30$n$, 2),
($n$2026-11-15-senco-gold-q2$n$, '2026-11-15', $n$local$n$, $n$RESULTS$n$,
  $n$Kolkata's Senco Gold lifts September-quarter profit 71% to ₹83.5 crore as revenue rises 34% despite record gold prices$n$,
  $n$Kolkata-based jeweller Senco Gold reported a consolidated net profit of ₹83.5 crore for the July-September quarter, up 71% from ₹48.8 crore a year earlier. Consolidated revenue rose 34% to ₹2,058.7 crore, and same-store sales grew 19%, even though gold traded between ₹1.4 lakh and ₹1.5 lakh per 10 grams during the quarter. For the first half of the year, revenue climbed 52% to ₹5,114.8 crore and profit rose 22% to ₹187.8 crore. The company opened 14 showrooms in the half, taking its network to 215 outlets, of which 123 are company-owned and 92 are franchise stores, and plans six to seven more in the second half.$n$,
  $n$The law of demand says people buy less of a product as its price rises, but gold is a known exception: it is bought as jewellery, savings and tradition, and rising prices can even make buyers expect further gains. Senco's growth at near-record gold prices shows how the law can bend.$n$,
  $n$Millennium Post; also Free Press Journal$n$, $n$https://www.millenniumpost.in/business/senco-gold-consolidated-net-profit-rises-71-to-835-crore-in-sept-qtr-683255$n$, $n$econ-01$n$, 'draft',
  $n$Gold cost over ₹1.4 lakh per 10 grams, yet Kolkata's own Senco Gold sold 34% more and grew profit 71%.$n$,
  $n$Senco Gold's sales and profit rose sharply in the September quarter even with gold near record prices, and it now has 215 outlets. Higher prices did not scare buyers away. The law of demand card explains when the usual rule breaks.$n$, true, $n$2026-11-15T00:00:00+05:30$n$, 3),
($n$2026-11-15-microsoft-outage-restored$n$, '2026-11-15', $n$global$n$, $n$TECH$n$,
  $n$Microsoft says Outlook, Teams and Copilot fully restored after global outage it blames on a network upgrade$n$,
  $n$Microsoft said on Saturday that it had fully restored services after an outage that disrupted Outlook, Teams, Copilot and other Microsoft 365 tools in more than 70 countries. Problems began around midday Thursday US time, and email issues continued into Friday because recovery was gradual. Microsoft said a technical problem during a network capacity upgrade caused the incident, and that there was no sign of a cyberattack. The disruption hit courts, police and pharmacies in the UK and government email in countries including Japan, Singapore and Australia. Microsoft 365 has more than 430 million users, and some lawmakers outside the US said the outage showed the risk of relying heavily on American tech firms.$n$,
  $n$In B2B buying, organisations often settle into a 'straight rebuy', renewing the same supplier without much thought. A major failure like this can prompt buying centres to reconsider and move to a 'modified rebuy', weighing backups or alternatives.$n$,
  $n$Millennium Post (AP); also Outlook India$n$, $n$https://www.millenniumpost.in/business/microsoft-says-services-fully-restored-after-hourslong-global-outage-683249$n$, $n$mkt-09$n$, 'draft',
  $n$One network upgrade at Microsoft froze Outlook and Teams for offices in more than 70 countries.$n$,
  $n$Courts, police and government ministries lost email and chat until Microsoft restored services on Saturday. Some lawmakers now question relying so heavily on one supplier. The B2B buying card explains how organisations choose and switch the suppliers they depend on.$n$, false, $n$2026-11-14T16:15:00+05:30$n$, 4),
($n$2026-11-15-brent-weekly-loss$n$, '2026-11-15', $n$global$n$, $n$OIL$n$,
  $n$Brent ends at $95.84, down about 2.5% for a second straight weekly loss as supply worries ease$n$,
  $n$Brent crude settled at $95.84 a barrel on Friday, up just 2 cents on the day but about 2.5% lower for the week, its second weekly decline in a row after a fall of about 16% the week before. US crude (WTI) settled at $88.56. Prices are now roughly 20% below their late-October high near $118. Higher OPEC+ output in October and rising US crude and fuel stocks weighed on prices, while reported attacks claimed by the Houthis on Saudi oil facilities had not been independently confirmed by the close. FinanceFeeds sketched a base-case range of about $94 to $97 for the coming week, stressing these were reference levels rather than forecasts.$n$,
  $n$When supply grows faster than demand, stockpiles build up and the market moves towards a surplus, pushing the price down until a new equilibrium is reached. Rising inventories and higher OPEC+ output are exactly that signal.$n$,
  $n$FinanceFeeds; also EnergyNow$n$, $n$https://financefeeds.com/brent-crude-oil-price-95-84-saturday-week-ahead-second-weekly-loss-bull-98-bear-91/$n$, $n$econ-09$n$, 'draft',
  $n$Oil has fallen about 20% from its October peak, and that matters for India's import bill.$n$,
  $n$Brent slipped for a second straight week as OPEC+ pumped more and US stockpiles grew. Cheaper crude eases pressure on India, which imports most of its oil. The market equilibrium card explains how surpluses push prices down.$n$, false, $n$2026-11-14T12:20:00+05:30$n$, 5),
($n$2026-11-15-musk-nvidia-handshake$n$, '2026-11-15', $n$global$n$, $n$GLOBAL COMPANIES$n$,
  $n$Elon Musk warns Nvidia could lose key supply deals without Jensen Huang, saying many were handshakes, not contracts$n$,
  $n$Tesla and SpaceX chief Elon Musk said on X that Nvidia could lose some critical supply chain deals after Jensen Huang's resignation as CEO, because many of them rested on Huang's personal word rather than written contracts. Musk also said he was signing a petition to bring Huang back. Huang, who co-founded Nvidia in 1993, resigned this week amid scrutiny over reports about his personal relationships, and finance chief Colette Kress is serving as interim CEO while the board searches for a successor. Musk replied that it 'would be an honor' when a user suggested he hire Huang.$n$,
  $n$Every contract is an agreement, but not every agreement is a contract: it needs the elements the law requires to be enforceable. Musk's point is that deals resting on one person's handshake may not survive that person leaving.$n$,
  $n$ANI; also The Tribune (ANI)$n$, $n$https://www.aninews.in/news/business/nvidia-risks-losing-critical-supply-chain-deals-without-jensen-huang-warns-elon-musk20261114205434/$n$, $n$law-01$n$, 'draft',
  $n$Nvidia's chip deals may have run on handshakes. Elon Musk says some could walk out with Jensen Huang.$n$,
  $n$Musk argued that many of Nvidia's supply arrangements relied on Huang's word rather than written contracts, and backed a petition to reinstate him. That raises a classic question for any business. The agreement vs contract card explains the difference.$n$, false, $n$2026-11-14T20:54:00+05:30$n$, 6),
($n$2026-11-15-patanjali-foods-q2$n$, '2026-11-15', $n$recruiter$n$, $n$RESULTS$n$,
  $n$Patanjali Foods' Q2 revenue rises 15.6% to ₹11,323 crore as edible oils hit a record ₹8,532 crore$n$,
  $n$Patanjali Foods reported consolidated revenue from operations of ₹11,322.58 crore for the September quarter, up 15.55% from ₹9,798.84 crore a year earlier, in results released on Saturday. Edible oils, its biggest business, posted record quarterly revenue of ₹8,532.25 crore, up 22.39%, but earned a segment margin of only about 3%. The FMCG segment brought in ₹2,923.48 crore at a margin of about 7.6%, and biscuits hit a record ₹638.31 crore. Company-level operating EBITDA was ₹425.63 crore, a margin of 3.76%, and profit before tax was ₹409.02 crore. The company expects the wedding season to support growth.$n$,
  $n$The income statement shows that revenue is only the top line: what matters is how much survives as EBITDA and profit before tax. Patanjali's thin margins on edible oil, compared with fatter FMCG margins, show why analysts read the segment numbers, not just total sales.$n$,
  $n$The Tribune (ANI)$n$, $n$https://www.tribuneindia.com/news/business/patanjali-foods-q2-revenue-rises-15-55-to-rs-11323-crore-edible-oil-business-hits-record-high/$n$, $n$acct-10$n$, 'draft',
  $n$Patanjali sold ₹11,323 crore in a quarter but kept under 4 paise of each rupee as operating profit.$n$,
  $n$Edible oils drove record sales at Patanjali Foods, yet that business earns only about a 3% margin, while biscuits and other FMCG products earn more. The top line hides what really drives profit. The financial statements card shows how to read past it.$n$, false, $n$2026-11-14T18:22:00+05:30$n$, 7),
($n$2026-11-15-trai-spam-crackdown$n$, '2026-11-15', $n$india$n$, $n$REGULATION$n$,
  $n$TRAI bars or disconnects over 1.24 lakh phone connections for spam in July-September; 15.29 lakh complaints received$n$,
  $n$Telecom regulator TRAI said 1,10,325 mobile numbers and other telecom resources were barred from making outgoing calls for 15 days in July-September for a first breach of rules on unsolicited commercial communication, and 13,777 were disconnected for a year for repeat offences. It also blocked 3,725 SMS headers and blacklisted 374 senders for a year. TRAI received 15.29 lakh spam complaints in the quarter, of which 7.23 lakh could be acted on. Operators' AI systems flagged about 19.9 billion calls and messages as suspected spam. Only about 22.4 crore of India's 134.9 crore subscribers, or 16.64%, have registered do-not-disturb preferences.$n$,
  $n$Marketing ethics asks whether the way a firm reaches customers respects their consent and choices. Unwanted promotional calls and SMSes are a clear case where aggressive marketing crosses into practices regulators now punish.$n$,
  $n$Millennium Post; also Free Press Journal$n$, $n$https://www.millenniumpost.in/business/trai-crackdown-on-spam-over-124-lakh-mobile-connections-barred-or-disconnected-in-jul-sep-683225$n$, $n$mkt-12$n$, 'draft',
  $n$Over 1.24 lakh phone numbers were cut off or barred for spam in three months. Your phone may still ring.$n$,
  $n$TRAI acted on lakhs of complaints, yet fewer than 17% of subscribers have signed up for do-not-disturb protection. Telemarketing that ignores consent is now a regulatory risk. The marketing ethics card explains where persuasion ends and misconduct begins.$n$, false, $n$2026-11-14T10:00:00+05:30$n$, 8),
($n$2026-11-15-vaishnaw-chip-machines$n$, '2026-11-15', $n$india$n$, $n$POLICY$n$,
  $n$India must build its own chipmaking machines and precision parts, says Ashwini Vaishnaw as Semicon 2.0 opens$n$,
  $n$Electronics and IT Minister Ashwini Vaishnaw said on Saturday that India needs to design and make its own machinery and high-precision components for semiconductor manufacturing. He spoke during a visit to Ethereal Machines' facility in Bengaluru, which makes advanced machinery and precision parts. The government opened applications on November 6 for Semicon 2.0, which has an approved outlay of ₹1,27,500 crore and offers incentives to makers of chip machinery, materials, chemicals and gases. Under the first phase of the Semicon India Programme, 12 projects worth over ₹1.64 lakh crore were approved across six states, and five had started commercial production by October.$n$,
  $n$The production possibility frontier shows the most an economy can produce with its resources and technology. Building capital goods such as chipmaking machines expands that capacity, shifting the frontier outward over time.$n$,
  $n$The Tribune (ANI)$n$, $n$https://www.tribuneindia.com/news/business/india-must-develop-its-own-semiconductor-manufacturing-machines-precision-components-ashwini-vaishnaw/$n$, $n$econ-07$n$, 'draft',
  $n$India is building chip factories. Now it wants to build the machines that make the chips, too.$n$,
  $n$Vaishnaw urged home-grown chipmaking tools as the ₹1.27 lakh crore Semicon 2.0 scheme opens, with five first-phase chip projects already in production. Making machines today raises what the country can produce tomorrow. The production possibility frontier card explains the idea.$n$, false, $n$2026-11-14T20:02:00+05:30$n$, 9),
($n$2026-11-15-eepc-east-bengal-policy$n$, '2026-11-15', $n$local$n$, $n$BENGAL$n$,
  $n$EEPC India honours 39 eastern-region engineering exporters; chairman backs West Bengal's new industrial policy$n$,
  $n$Commerce Secretary Rajesh Agrawal presented 39 awards to engineering goods exporters from eastern India at the 42nd EEPC India Eastern Regional Awards, which recognised performance in FY24. India's engineering exports rose 2.13% to $109.3 billion that year despite weak global trade and geopolitical conflicts. EEPC India chairman Pankaj Chadha thanked the West Bengal government for its new industrial policy, saying it aims to make the state a hub for manufacturing, technology and services through job-linked incentives and faster approvals. He said the policy puts small businesses and engineering at the centre. The state unveiled its Investment Promotion Policy 2026 earlier this month.$n$,
  $n$Incentives and faster approvals lower the cost of producing in a place, which shifts the supply curve: firms are willing to produce more at every price. Bengal's policy is a bet that cheaper, easier production will draw new factories.$n$,
  $n$Millennium Post; also The Week$n$, $n$https://www.millenniumpost.in/business/eepc-india-honours-39-engineering-goods-exporters-from-eastern-region-for-their-performance-in-fy24-683253$n$, $n$econ-08$n$, 'draft',
  $n$Exporters from eastern India won 39 awards, and Bengal's new industrial policy won a vote of confidence.$n$,
  $n$EEPC India's chairman praised West Bengal's job-linked incentives and faster approvals as the state courts factories. Policies like this aim to make producing in Bengal cheaper and easier. The law of supply card explains what shifts how much firms are willing to make.$n$, false, $n$2026-11-15T02:00:00+05:30$n$, 10),
($n$2026-11-15-cci-advent-yatharth$n$, '2026-11-15', $n$india$n$, $n$DEALS$n$,
  $n$CCI clears Advent International-backed firm's stake purchase in Yatharth Hospitals$n$,
  $n$The Competition Commission of India on Saturday approved the purchase of a stake in Yatharth Hospital & Trauma Care Services by Rasmalai Limited. Rasmalai is a Cyprus-based holding company that is indirectly controlled by funds managed or advised by global private equity firm Advent International, and it has no business operations in India. Yatharth runs a chain of super-speciality hospitals in India. The regulator did not disclose how large a stake is being bought or what the deal is worth.$n$,
  $n$Competition regulators review deals to make sure no buyer gains enough market power to weaken rivalry. Porter's Five Forces is the framework managers use to judge how intense competition in an industry like hospitals really is.$n$,
  $n$The Tribune (ANI)$n$, $n$https://www.tribuneindia.com/news/business/cci-approves-advent-international-backed-firms-stake-acquisition-in-yatharth-hospitals/$n$, $n$mkt-06$n$, 'draft',
  $n$A global private equity giant is buying into an Indian hospital chain, and the competition watchdog said yes.$n$,
  $n$The CCI approved an Advent-backed company's stake purchase in Yatharth Hospitals, without revealing its size or price. Private equity keeps betting on Indian healthcare. Porter's Five Forces card explains how to judge an industry's competitive pull.$n$, false, $n$2026-11-14T20:02:00+05:30$n$, 11),
($n$2026-11-15-pollution-insurance-claims$n$, '2026-11-15', $n$india$n$, $n$INSURANCE$n$,
  $n$Pollution-linked health insurance claims rose 4.3 times between FY23 and FY26, Policybazaar data shows$n$,
  $n$Health insurance claims linked to air pollution rose 4.34 times between FY23 and FY26, and the total amount claimed rose 4.5 times, according to data from insurance platform Policybazaar. Heart and blood-vessel conditions made up 43.5% of these claims and respiratory infections 35%. Working professionals aged 31 to 55 filed 59% of the claims, and smaller tier-2 and tier-3 cities accounted for 55%, though Delhi had the most. About 56% of FY26 claims came between October and March, when pollution usually peaks, and 48% of buyers in highly polluted cities chose higher cover.$n$,
  $n$A change in demand happens when something other than price, such as health risk, makes people want more of a product at every price. Pollution pushing buyers towards bigger health cover is a shift in the whole demand curve, not a movement along it.$n$,
  $n$The Tribune (ANI)$n$, $n$https://www.tribuneindia.com/news/business/pollution-linked-health-insurance-claims-rise-4-3-times-in-three-years-shows-policybazaar-data/$n$, $n$econ-02$n$, 'draft',
  $n$Polluted air is showing up in insurance claims: up more than fourfold in three years, Policybazaar says.$n$,
  $n$Most claims came from working-age people, and nearly half of buyers in polluted cities chose higher cover. The risk, not the price, is changing what people buy. The change in demand card explains the difference.$n$, false, $n$2026-11-14T16:52:00+05:30$n$, 12)
on conflict (slug) do update set
  publish_date = excluded.publish_date, lane = excluded.lane, tag = excluded.tag,
  headline = excluded.headline, summary = excluded.summary, concept_note = excluded.concept_note,
  source_name = excluded.source_name, source_url = excluded.source_url, card_id = excluded.card_id,
  published_at = excluded.published_at, rank = excluded.rank,
  -- the pick and teaser only fill in blanks, so changes made on the approval page are kept
  teaser_title = coalesce(news_stories.teaser_title, excluded.teaser_title),
  teaser = coalesce(news_stories.teaser, excluded.teaser),
  featured = news_stories.featured or (excluded.featured and not exists (
    select 1 from news_stories f where f.publish_date = excluded.publish_date and f.featured));

-- Check: this day's stories by lane
select lane, count(*) as stories, count(*) filter (where status = 'approved') as approved,
  count(*) filter (where featured) as todays_pick
from news_stories where publish_date = '2026-11-15' group by lane order by lane;

-- Check: the day's running order
select rank, lane, headline, status, featured from news_stories where publish_date = '2026-11-15' order by rank;
